+
+void prf_addrx8(unsigned char *out0,
+                unsigned char *out1,
+                unsigned char *out2,
+                unsigned char *out3,
+                unsigned char *out4,
+                unsigned char *out5,
+                unsigned char *out6,
+                unsigned char *out7,
+                const spx_ctx *ctx,
+                const uint32_t addrx8[8*8])
+{
+    unsigned char *out[8] = {out0, out1, out2, out3, out4, out5, out6, out7};
+    int lane_rc[8] = {0};
+
+    for (unsigned int i = 0; i < 8; i++) {
+        const uint32_t *addr = addrx8 + 8 * i;
+        unsigned int src = i;
+
+        for (unsigned int j = 0; j < i; j++) {
+            if (lane_rc[j] == 0 && same_addr(addr, addrx8 + 8 * j)) {
+                src = j;
+                break;
+            }
+        }
+
+        if (src != i) {
+            if (out[i] != out[src]) {
+                memcpy(out[i], out[src], SPX_N);
+            }
+            continue;
+        }
+
+        lane_rc[i] = prf_addr_lane(out[i], ctx, addr);
+    }
+}
+
+void prf_addrx8_tree_index(unsigned char *out0,
+                           unsigned char *out1,
+                           unsigned char *out2,
+                           unsigned char *out3,
+                           unsigned char *out4,
+                           unsigned char *out5,
+                           unsigned char *out6,
+                           unsigned char *out7,
