+            for (j = 0; j < 8; j++) {
+                set_type(addrx8 + j * 8, SPX_ADDR_TYPE_WOTS);
+            }
+
+            for (k = 0;; k++) {
+                if (k == wots_k0) {
+                    memcpy(info->wots_sig + i * SPX_N,
+                           buffer0 + wots_sign_index * wots_offset, SPX_N);
