+                        buffer0 + 1 * wots_offset,
+                        buffer0 + 2 * wots_offset,
+                        buffer0 + 3 * wots_offset,
+                        buffer1 + 0 * wots_offset,
+                        buffer1 + 1 * wots_offset,
