+		return pseudohash_512(msg, msg_len_bits, digest);
+	}
+	else if (digest_len_bits == 768)
+	{
+		return pseudohash_768(msg, msg_len_bits, digest);
+	}
+	else if (digest_len_bits == 1024)
+	{
+		return pseudohash_1024(msg, msg_len_bits, digest);
