+    memcpy(buf, ctx->pub_seed, SPX_N);
+    memcpy(buf + SPX_N, addr, SPX_ADDR_BYTES);
+    memcpy(buf + SPX_N + SPX_ADDR_BYTES, ctx->sk_seed, SPX_N);
