+        sm3hash(256, buf, in_len_bits, temp_out);
+        memcpy(out, temp_out, SPX_N);
+    } else {
+        unsigned long long out_len_bits = (unsigned long long)SPX_N * 8;
+        pseudoXOF(out_len_bits, buf, in_len_bits, out);
