+                thashx8(digestx8[0], digestx8[1], digestx8[2], digestx8[3],
+                        digestx8[4], digestx8[5], digestx8[6], digestx8[7],
+                        root, root, root, root, root, root, root, root,
+                        1, ctx, pk_addrx8);
