+    int rc = 0;
+    const unsigned char *msg[8] = {msg0, msg1, msg2, msg3,
+                                   msg4, msg5, msg6, msg7};
+    unsigned char *digest[8] = {digest0, digest1, digest2, digest3,
+                                digest4, digest5, digest6, digest7};
