+    /*hashes message with counter, so last X bits are zero*/
+    counter = 0;
+    if (hash_message(mhash, &tree, &idx_leaf, sig, pk, m, mlen, &ctx, &counter) == -1)
+        return -1;
+    save_fors_counter(counter,sig);
+    sig += SPX_N + COUNTER_SIZE;
+
+    set_tree_addr(wots_addr, tree);
+    set_keypair_addr(wots_addr, idx_leaf);
+
+    /* Sign the message hash using FORS. */
+    fors_sign(sig, root, mhash, &ctx, wots_addr);
+
+    sig += SPX_FORS_BYTES;
+    
+    uint32_t merkle_tree_heights[SPX_D];
+    uint32_t num_k = SPX_FULL_HEIGHT - SPX_TREE_HEIGHT*SPX_D;
+    for (uint32_t j = 0; j < num_k; j++) {
+        merkle_tree_heights[j] = SPX_TREE_HEIGHT+1;
+    }
+    for (uint32_t j = num_k; j < SPX_D; j++) {
+        merkle_tree_heights[j] = SPX_TREE_HEIGHT;
+    }
+
+    for (i = 0; i < SPX_D; i++) {
+        set_layer_addr(tree_addr, i);
+        set_tree_addr(tree_addr, tree);
+
+        copy_subtree_addr(wots_addr, tree_addr);
+        set_keypair_addr(wots_addr, idx_leaf);
+
+        merkle_sign(sig, root, &ctx, wots_addr, tree_addr, idx_leaf, &counter,merkle_tree_heights[i]);
+        if (counter == 0)
+            return -1;
+        save_wots_counter(counter, sig,merkle_tree_heights[i]);
+        sig += SPX_WOTS_BYTES + merkle_tree_heights[i] * SPX_N + COUNTER_SIZE;
+        /* Update the indices for the next layer. */
+        if (i + 1 < SPX_D) {
+            idx_leaf = (tree & ((1 << merkle_tree_heights[i + 1]) - 1));
+            tree = tree >> merkle_tree_heights[i + 1];
+        }
+    }
+
+    *siglen = SPX_BYTES;
+
+    return 0;
+}
+
+/**
+ * Verifies a detached signature and message under a given public key.
+ */
+int crypto_sign_verify(const uint8_t *sig, size_t siglen,
+                       const uint8_t *m, size_t mlen, const uint8_t *pk)
+{
+    spx_ctx ctx;
+    const unsigned char *pub_root = pk + SPX_N;
+    unsigned char mhash[SPX_FORS_MSG_BYTES];
+    unsigned char wots_pk[SPX_WOTS_BYTES];
+    unsigned char root[SPX_N];
+    unsigned char leaf[SPX_N];
+    unsigned int i;
+    uint64_t tree;
+    uint32_t idx_leaf;
+    uint32_t wots_addr[8] = {0};
+    uint32_t tree_addr[8] = {0};
+    uint32_t wots_pk_addr[8] = {0};
+    uint32_t counter;
+
+    if (siglen != SPX_BYTES) {
+        return -1;
+    }
+    
+    memcpy(ctx.pub_seed, pk, SPX_N);
+
+    /* This hook allows the hash function instantiation to do whatever
+       preparation or computation it needs, based on the public seed. */
+    initialize_hash_function(&ctx);
+
+    set_type(wots_addr, SPX_ADDR_TYPE_WOTS);
+    set_type(tree_addr, SPX_ADDR_TYPE_HASHTREE);
+    set_type(wots_pk_addr, SPX_ADDR_TYPE_WOTSPK);
+
+    /* Derive the message digest and leaf index from R || PK || M. */
+    /* The additional SPX_N is a result of the hash domain separator. */
+    counter = get_fors_counter(sig);
+    if (counter == 0)
+        return -1;
+    if (hash_message(mhash, &tree, &idx_leaf, sig, pk, m, mlen, &ctx, &counter) == -1)
+        return -1;
+    sig += SPX_N + COUNTER_SIZE;
+
+    /* Layer correctly defaults to 0, so no need to set_layer_addr */
+    set_tree_addr(wots_addr, tree);
+    set_keypair_addr(wots_addr, idx_leaf);
+    fors_pk_from_sig(root, sig, mhash, &ctx, wots_addr);
+    sig += SPX_FORS_BYTES;
+    
+    uint32_t merkle_tree_heights[SPX_D];
+    uint32_t num_k = SPX_FULL_HEIGHT - SPX_TREE_HEIGHT*SPX_D;
+    for (uint32_t j = 0; j < num_k; j++) {
+        merkle_tree_heights[j] = SPX_TREE_HEIGHT+1;
+    }
+    for (uint32_t j = num_k; j < SPX_D; j++) {
+        merkle_tree_heights[j] = SPX_TREE_HEIGHT;
+    }
+
+    /* For each subtree.. */
+    for (i = 0; i < SPX_D; i++) {
+        set_layer_addr(tree_addr, i);
+        set_tree_addr(tree_addr, tree);
+
+        copy_subtree_addr(wots_addr, tree_addr);
+        set_keypair_addr(wots_addr, idx_leaf);
+
+        copy_keypair_addr(wots_pk_addr, wots_addr);
+
+        /* The WOTS public key is only correct if the signature was correct. */
+        /* Initially, root is the FORS pk, but on subsequent iterations it is
+           the root of the subtree below the currently processed subtree. */
+        counter = get_wots_counter(sig,merkle_tree_heights[i]);
+        if (counter == 0)
+            return -1;
+        wots_pk_from_sig(wots_pk, sig, root, &ctx, wots_addr, counter);
+        sig += SPX_WOTS_BYTES;
+
+        /* Compute the leaf node using the WOTS public key. */
+        thash(leaf, wots_pk, SPX_WOTS_LEN, &ctx, wots_pk_addr);
+        /* Compute the root node of this subtree. */
+        compute_root(root, leaf, idx_leaf, 0, sig, merkle_tree_heights[i],
+                     &ctx, tree_addr);
+        sig += merkle_tree_heights[i] * SPX_N  + COUNTER_SIZE;
+
+        /* Update the indices for the next layer. */
+        if (i + 1 < SPX_D) {
+            idx_leaf = (tree & ((1 << merkle_tree_heights[i + 1]) - 1));
+            tree = tree >> merkle_tree_heights[i + 1];
+        }
+    }
+
+    /* Check if the root node equals the root node in the public key. */
+    if (memcmp(root, pub_root, SPX_N)) {
+        return -1;
+    }
+
+    return 0;
+}
+
+
+/**
+ * Returns an array containing the signature followed by the message.
+ */
+int crypto_sign(unsigned char *sm, unsigned long long *smlen,
+                const unsigned char *m, unsigned long long mlen,
+                const unsigned char *sk)
+{
+    size_t siglen;
+
+    crypto_sign_signature(sm, &siglen, m, (size_t)mlen, sk);
+
+    memmove(sm + SPX_BYTES, m, mlen);
+    *smlen = siglen + mlen;
+
+    return 0;
+}
+
+/**
+ * Verifies a given signature-message pair under a given public key.
+ */
+int crypto_sign_open(unsigned char *m, unsigned long long *mlen,
+                     const unsigned char *sm, unsigned long long smlen,
+                     const unsigned char *pk)
+{
+    /* The API caller does not necessarily know what size a signature should be
+       but SPHINCS+ signatures are always exactly SPX_BYTES. */
+    if (smlen < SPX_BYTES) {
+        memset(m, 0, smlen);
+        *mlen = 0;
+        return -1;
+    }
+
+    *mlen = smlen - SPX_BYTES;
+
+    if (crypto_sign_verify(sm, SPX_BYTES, sm + SPX_BYTES, (size_t)*mlen, pk)) {
+        memset(m, 0, smlen);
+        *mlen = 0;
+        return -1;
+    }
+
+    /* If verification was successful, move the message to the right place. */
+    memmove(m, sm + SPX_BYTES, *mlen);
+
+    return 0;
+}

