+void save_wots_counter(uint32_t counter, unsigned char *sig,uint32_t merkle_tree_height) {
+    unsigned char counter_bytes[COUNTER_SIZE];
+
+    ull_to_bytes(counter_bytes, COUNTER_SIZE, counter);
