+#define MIN_INT(a, b) ((a) < (b) ? (a) : (b))
+#define MAX_INT(a, b) ((a) > (b) ? (a) : (b))
+#define DIVISION_ROUND_UP(dividend, divisor, result) \
+    do                                               \
+    {                                                \
+        (result) = (dividend) / (divisor);           \
+        if ((dividend) % (divisor))                  \
+            (result)++;                              \
+    } while (0)
