+    const unsigned long long output_len_bytes = (output_len_bits + 7u) >> 3;
+    int lane_rc[8] = {0};
+
+    for (unsigned int i = 0; i < 8; i++) {
+        unsigned int src = i;
+
+        for (unsigned int j = 0; j < i; j++) {
+            if (lane_rc[j] == 0 && msg[i] == msg[j]) {
