+            free(hash_in);
+            return -1;
+        }
+    }
+    /*sign stage, searches for counter*/
+    else
+    {
+        while(found_flag)
+        {
+            //counter should be 1 or larger.
+            (*counter)++;
+            if (*counter > MAX_HASH_TRIALS_FORS) {
+                free(hash_in);
+                return -1;
+            }
+            ull_to_bytes(counter_ptr, COUNTER_SIZE, *counter);
+            pseudoXOF(out_len_bits, hash_in, in_len_bits, buf);
